//! Slide layout templates and automatic placeholder geometry resolution.

use alloc::vec::Vec;
use sex_canvas::Rect;

/// Standard slide layouts.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SlideLayout {
    TitleSlide,
    TitleAndBody,
    SectionHeader,
    TwoColumn,
    TitleAndImage,
    Blank,
}

impl Default for SlideLayout {
    fn default() -> Self {
        Self::TitleAndBody
    }
}

/// Kinds of content placeholders generated by a layout.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PlaceholderKind {
    Title,
    Subtitle,
    Body,
    Column1,
    Column2,
    Image,
    Header,
}

/// A resolved placeholder bounding box on the slide canvas.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PlaceholderBox {
    pub kind: PlaceholderKind,
    pub bounds: Rect,
}

impl PlaceholderBox {
    pub const fn new(kind: PlaceholderKind, bounds: Rect) -> Self {
        Self { kind, bounds }
    }
}

/// Resolves placeholder bounding boxes for a given layout and canvas dimensions.
pub fn resolve_placeholders(layout: SlideLayout, width: f32, height: f32) -> Vec<PlaceholderBox> {
    if !width.is_finite() || !height.is_finite() || width <= 0.0 || height <= 0.0 {
        return Vec::new();
    }
    let mut boxes = Vec::new();
    let margin_x = width * 0.08;
    let margin_y = height * 0.08;
    let content_w = width - margin_x * 2.0;

    match layout {
        SlideLayout::TitleSlide => {
            let title_y = height * 0.32;
            let title_h = height * 0.22;
            let sub_y = height * 0.56;
            let sub_h = height * 0.16;
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Title,
                Rect::new(margin_x, title_y, content_w, title_h),
            ));
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Subtitle,
                Rect::new(margin_x, sub_y, content_w, sub_h),
            ));
        }
        SlideLayout::TitleAndBody => {
            let title_h = height * 0.14;
            let body_y = margin_y + title_h + height * 0.04;
            let body_h = height - body_y - margin_y;
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Title,
                Rect::new(margin_x, margin_y, content_w, title_h),
            ));
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Body,
                Rect::new(margin_x, body_y, content_w, body_h),
            ));
        }
        SlideLayout::SectionHeader => {
            let header_y = height * 0.38;
            let header_h = height * 0.24;
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Header,
                Rect::new(margin_x, header_y, content_w, header_h),
            ));
        }
        SlideLayout::TwoColumn => {
            let title_h = height * 0.14;
            let body_y = margin_y + title_h + height * 0.04;
            let body_h = height - body_y - margin_y;
            let col_gap = width * 0.04;
            let col_w = (content_w - col_gap) / 2.0;
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Title,
                Rect::new(margin_x, margin_y, content_w, title_h),
            ));
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Column1,
                Rect::new(margin_x, body_y, col_w, body_h),
            ));
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Column2,
                Rect::new(margin_x + col_w + col_gap, body_y, col_w, body_h),
            ));
        }
        SlideLayout::TitleAndImage => {
            let title_h = height * 0.14;
            let body_y = margin_y + title_h + height * 0.04;
            let body_h = height - body_y - margin_y;
            let gap = width * 0.04;
            let left_w = (content_w - gap) * 0.52;
            let right_w = content_w - gap - left_w;
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Title,
                Rect::new(margin_x, margin_y, content_w, title_h),
            ));
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Body,
                Rect::new(margin_x, body_y, left_w, body_h),
            ));
            boxes.push(PlaceholderBox::new(
                PlaceholderKind::Image,
                Rect::new(margin_x + left_w + gap, body_y, right_w, body_h),
            ));
        }
        SlideLayout::Blank => {}
    }

    boxes
}
